import json, re, subprocess
from datetime import datetime, timezone
from pathlib import Path
REPO = Path("/Users/sab-mini/repos/MyAPI")
HEAD_PIN = "131a143fa0bfa4151645a29fedb80f99c7df1055"
REC_SEP="\x1e"; END_SEP="\x1f"
COMMIT_FMT = REC_SEP.join(["%H","%P","%at","%ct","%aN","%cN"]) + REC_SEP + "%B" + END_SEP
def git(*a):
    r=subprocess.run(["git",*a],cwd=REPO,capture_output=True,text=True)
    return r.stdout
def iso(u): return datetime.fromtimestamp(int(u),tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
head=git("rev-parse",HEAD_PIN).strip(); total=int(git("rev-list","--count",HEAD_PIN).strip())
meta=git("log","--reverse","--topo-order",HEAD_PIN,f"--format={COMMIT_FMT}")
entries=[]; by={}
for rec in meta.split(END_SEP):
    rec=rec.strip("\n")
    if not rec.strip(): continue
    sha,par,at,ct,an,cn,body=rec.split(REC_SEP)
    e={"commit":sha,"parents":par.split() if par else [],"authored_at":iso(at),"committed_at":iso(ct),
       "author":an,"committer":cn,"message":body.strip("\n"),"files":[]}
    entries.append(e); by[sha]=e
raw=git("log","--reverse","--topo-order","--numstat",HEAD_PIN,"--format=%H")
cur=None
for line in raw.splitlines():
    if not line.strip(): continue
    if len(line)==40 and all(c in "0123456789abcdef" for c in line): cur=by[line]
    elif cur is not None:
        p=line.split("\t")
        if len(p)==3:
            a,d,path=p
            cur["files"].append({"path":path,"status":"binary" if a=="-" else "text",
                "lines_added":None if a=="-" else int(a),"lines_deleted":None if d=="-" else int(d)})
reb={e["commit"]:e for e in entries}
disk=[]
for l in Path("part2/layers/git/git-export.jsonl").read_text().splitlines():
    if l.strip(): disk.append(json.loads(l))
dmap={e["commit"]:e for e in disk[1:]}
print("disk entries:",len(disk)-1,"| rebuild entries:",len(entries),"| disk commit_count field:",disk[0]["commit_count"])
n_diff=0; diff_shas=[]
for sha,e in reb.items():
    d=dmap.get(sha)
    if d is None: n_diff+=1; diff_shas.append((sha,"missing")); continue
    # compare everything except files counts: compare commit-level fields exactly
    for k in ("commit","parents","authored_at","committed_at","author","committer","message"):
        if e[k]!=d[k]:
            n_diff+=1; diff_shas.append((sha,"field "+k)); break
    else:
        # compare files structure
        if len(e["files"])!=len(d["files"]):
            n_diff+=1; diff_shas.append((sha,"file-count")); continue
        for fe,fd in zip(e["files"],d["files"]):
            if fe!=fd:
                n_diff+=1; diff_shas.append((sha,"file-bytes")); break
print("entries differing from disk:",n_diff)
for sha,why in diff_shas[:20]: print("  ",sha[:12],why)
# how many differing entries differ ONLY in lines_added/lines_deleted vs also paths
only_counts=0
for sha,e in reb.items():
    d=dmap.get(sha)
    if d is None: continue
    if len(e["files"])!=len(d["files"]): continue
    diff=False; pathdiff=False
    for fe,fd in zip(e["files"],d["files"]):
        if fe!=fd:
            diff=True
            if fe["path"]!=fd["path"] or fe["status"]!=fd["status"]: pathdiff=True
    if diff and not pathdiff: only_counts+=1
print("entries differing only in add/del counts:",only_counts)
EOF
